package com.xjtu.iron.idempotent.starter;import com.xjtu.iron.idempotent.core.observation.*;import org.springframework.context.ApplicationEventPublisher;/** 事件 listener 异常必须与正确性主流程隔离。 */public final class SpringIdempotencyEventPublisher implements IdempotencyEventPublisher{private final ApplicationEventPublisher publisher;public SpringIdempotencyEventPublisher(ApplicationEventPublisher publisher){this.publisher=publisher;}public void publish(IdempotencyEvent event){try{publisher.publishEvent(event);}catch(RuntimeException ignored){}}}
